    CONSTRAINT long_term_assets_asset_type_check CHECK (((asset_type)::text = ANY ((ARRAY['REAL_ESTATE'::character varying, 'BOND'::character varying, 'DEPOSIT'::character varying, 'CASH_RESERVE'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT long_term_assets_current_value_check CHECK ((current_value >= (0)::numeric)),
    CONSTRAINT long_term_assets_name_check CHECK ((btrim((name)::text) <> ''::text)),
    CONSTRAINT long_term_assets_tax_base_check CHECK (((tax_base IS NULL) OR (tax_base >= (0)::numeric)))
);


