reconciliation_reporting_scale	0.000000000000	Decimal places used for displayed reconciliation values.
reconciliation_absolute_tolerance	0.050000000000	Shared absolute monetary tolerance.
reconciliation_relative_tolerance	0.000010000000	Shared relative monetary tolerance.
reconciliation_quantity_tolerance	0.000001000000	Tolerance for signed quantity matching; not a monetary tolerance.
reconciliation_trade_cash_absolute_tolerance	5.000000000000	Domain threshold for trade cash settlement differences.
reconciliation_trade_cash_relative_tolerance	0.050000000000	Domain threshold for trade cash settlement differences.
reconciliation_carrying_value_absolute_threshold	250.000000000000	Domain threshold for carrying-value outliers.
reconciliation_carrying_value_relative_threshold	0.500000000000	Domain threshold for carrying-value outliers.
reconciliation_reorganization_absolute_threshold	250.000000000000	Domain threshold for reorganization value jumps.
reconciliation_reorganization_relative_threshold	0.200000000000	Domain threshold for reorganization value jumps.
reconciliation_market_bridge_absolute_threshold	250.000000000000	Domain threshold for market-value bridge outliers.
reconciliation_market_bridge_relative_threshold	0.200000000000	Domain threshold for market-value bridge outliers.
reconciliation_position_input_absolute_tolerance	0.050000000000	Input validation tolerance for position notional reconstruction.
reconciliation_position_input_relative_tolerance	0.150000000000	Input validation tolerance for position notional reconstruction.
reconciliation_local_sale_price_relative_threshold	0.050000000000	Domain threshold for local sale-vs-carrying-value comparison.
reconciliation_local_flat_base_jump_relative_threshold	0.150000000000	Domain threshold for local-flat/base-currency valuation jumps.
reconciliation_price_jump_upper_ratio	100.000000000000	Domain threshold for extreme upward price jumps.
reconciliation_price_jump_lower_ratio	0.010000000000	Domain threshold for extreme downward price jumps.
reconciliation_valuation_jump_upper_ratio	5.000000000000	Domain threshold for valuation-jump detection.
reconciliation_valuation_jump_lower_ratio	0.200000000000	Domain threshold for valuation-jump detection.
reconciliation_valuation_jump_trade_multiplier	1.250000000000	Domain threshold for valuation-jump trade allowance.
reconciliation_valuation_jump_absolute_threshold	250.000000000000	Domain threshold for valuation-jump detection.
reconciliation_source_disagreement_ratio	1.250000000000	Price-source disagreement ratio that requires review.
reconciliation_interpolation_deviation_ratio	0.250000000000	Interpolation deviation ratio that requires review.
reconciliation_reconstruction_window_days	90.000000000000	Number of recent calendar days retained by settlement reconciliation reconstruction.
long_term_default_rental_tax_rate	0.085000000000	Fallback annual rental-tax rate when no portfolio policy is effective.
